// Edge-runtime session verification for the /client dashboard gate.
// Uses Web Crypto (crypto.subtle) only - node:crypto is unavailable in the edge
// runtime where proxy.ts runs. Must stay in lockstep with lib/client-auth.ts
// (Node runtime), which signs the cookies this file verifies.
//
// Returns the client slug from the verified payload so the dashboard can scope
// its data fetch to that one tenant, and requires method === 'client' so a
// cookie minted by any other gate can never verify here even though they share
// SESSION_SECRET.
//
// Fails closed: returns null whenever SESSION_SECRET is unset or anything about
// the cookie is off.

export const CLIENT_COOKIE = "sol_client";
const MAX_AGE_MS = 7 * 24 * 60 * 60 * 1000; // 7 days
const SLUG_RE = /^[a-z0-9][a-z0-9-]{0,63}$/;

function enc(str: string): Uint8Array {
  return new TextEncoder().encode(str);
}

async function importKey(secret: string): Promise<CryptoKey> {
  return crypto.subtle.importKey(
    "raw",
    enc(secret) as BufferSource,
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign", "verify"],
  );
}

/** Constant-time comparison of two byte arrays. */
function safeEqual(a: Uint8Array, b: Uint8Array): boolean {
  if (a.byteLength !== b.byteLength) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a[i] ^ b[i];
  return diff === 0;
}

/** Decode a hex string to Uint8Array. Returns null on invalid input. */
function fromHex(hex: string): Uint8Array | null {
  if (typeof hex !== "string" || hex.length === 0 || hex.length % 2 !== 0) return null;
  const arr = new Uint8Array(hex.length / 2);
  for (let i = 0; i < arr.length; i++) {
    const byte = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
    if (Number.isNaN(byte)) return null;
    arr[i] = byte;
  }
  return arr;
}

/** An email longer than the RFC maximum is not one we minted. */
const MAX_EMAIL_LEN = 254;

export interface ClientSession {
  slug: string;
  email?: string;
  /** Every workspace slug this session may access, when it came from an
   *  email-based sign-in allowlisted into more than one workspace. `slug` is
   *  the first of these. Absent for a single-workspace (password) session. */
  slugs?: string[];
}

/** Does this session grant access to `requestedSlug`? A single-workspace
 *  session (no `slugs`) grants only its own `slug`, exactly as before. */
export function sessionGrantsSlug(session: ClientSession, requestedSlug: string): boolean {
  return session.slugs ? session.slugs.includes(requestedSlug) : session.slug === requestedSlug;
}

/**
 * Verify a /client session cookie. Returns { slug } only for a valid, unexpired,
 * client-method session signed with the current SESSION_SECRET; otherwise null.
 *
 * `email` rides along when the session came from an email-based sign-in. It is
 * attribution only - nothing gates on it - and it is optional, so a password
 * session and any cookie minted before the field existed still verify.
 */
export async function verifyClientSessionEdge(
  value: string,
): Promise<ClientSession | null> {
  const secret = process.env.SESSION_SECRET;
  if (!secret || typeof value !== "string") return null;

  const dotIdx = value.lastIndexOf(".");
  if (dotIdx === -1) return null;

  const payload = value.slice(0, dotIdx);
  const providedHex = value.slice(dotIdx + 1);

  const providedBytes = fromHex(providedHex);
  if (!providedBytes) return null;

  let key: CryptoKey;
  try {
    key = await importKey(secret);
  } catch {
    return null;
  }

  let expectedMac: Uint8Array;
  try {
    expectedMac = new Uint8Array(await crypto.subtle.sign("HMAC", key, enc(payload) as BufferSource));
  } catch {
    return null;
  }

  if (!safeEqual(expectedMac, providedBytes)) return null;

  let session: unknown;
  try {
    session = JSON.parse(atob(payload));
  } catch {
    return null;
  }
  if (
    !session ||
    typeof session !== "object" ||
    (session as { method?: unknown }).method !== "client" ||
    typeof (session as { slug?: unknown }).slug !== "string" ||
    typeof (session as { issuedAt?: unknown }).issuedAt !== "number"
  ) {
    return null;
  }
  const { slug, issuedAt, email, slugs } = session as {
    slug: string;
    issuedAt: number;
    email?: unknown;
    slugs?: unknown;
  };
  if (!SLUG_RE.test(slug)) return null;
  if (Date.now() - issuedAt >= MAX_AGE_MS) return null;

  // A malformed email is dropped rather than failing the session: it carries no
  // authority, so losing it costs an attribution label, not access.
  const clean =
    typeof email === "string" && email.length > 0 && email.length <= MAX_EMAIL_LEN
      ? email.toLowerCase()
      : undefined;

  // A malformed `slugs` array is dropped the same way: the session still
  // verifies as its single `slug`, just without the wider grant.
  const cleanSlugs =
    Array.isArray(slugs) && slugs.every((s) => typeof s === "string" && SLUG_RE.test(s)) && slugs.includes(slug)
      ? (slugs as string[])
      : undefined;

  const result: ClientSession = { slug };
  if (clean) result.email = clean;
  if (cleanSlugs) result.slugs = cleanSlugs;
  return result;
}

