const TENANT_A = "station-street-fitness";
const TENANT_B = "nomadik";
const DOC_A = `https://solaisoft.com/client-docs/${TENANT_A}/reference.html`;

/**
 * Mint a valid /client session cookie, mirroring lib/client-auth.ts exactly:
 * base64(JSON{method:"client", slug, issuedAt}) + "." + hex(HMAC-SHA256(payload)).
 */
async function mintClientCookie(
  slug: string,
  secret: string,
  issuedAt: number = Date.now(),
): Promise<string> {
  const payload = btoa(JSON.stringify({ method: "client", slug, issuedAt }));
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const mac = new Uint8Array(
    await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(payload)),
  );
  const hex = Array.from(mac, (b) => b.toString(16).padStart(2, "0")).join("");
  return `${payload}.${hex}`;
}

