export const config = {
  // Gate everything except Next internals, the favicon, and the public brand
  // logo (linked from the email signature, so it must load without the gate).
  matcher: ["/((?!_next/static|_next/image|favicon.ico|solaisoft-logo-coral.png).*)"],
};

